async function state(name,index,x,markerX){let l=await c('list_pages',{}),p=l.pages.find(q=>q.name===name);if(!p){await c('duplicate_page',{pageId:'n2032',name});l=await c('list_pages',{});p=l.pages.find(q=>q.name===name)}await c('reorder_page',{pageId:p.id,index:String(index)});l=await c('list_pages',{});await c('set_active_page',{index:String(l.pages.findIndex(q=>q.id===p.id))});const root=await c('batch_get',{depth:0});const frame=root.nodes[0];const a=await c('read_nodes',{nodeIds:[frame.id],depth:1,pageId:p.id});const ov=a.nodes[0].children.find(n=>n.name==='Foco de teclado · transición 100 ms');const b=await c('read_nodes',{nodeIds:[ov.id],depth:1,pageId:p.id});for(const n of b.nodes[0].children){if(n.name==='05A focus ring')await c('update_node',{nodeId:n.id,x:String(x),width:'166',height:'44',pageId:p.id});if(n.name==='05A focus marker')await c('update_node',{nodeId:n.id,x:String(markerX),pageId:p.id});}return{pageId:p.id,frameId:frame.id,overlayId:ov.id}}
(async()=>{console.log(await state('05A Estado de foco · Clase',7,420,430));console.log(await state('05A Estado de foco · Tipo',8,586,596));})().catch(e=>{console.error(e);process.exit(1)});

