const ep = 'http://127.0.0.1:3100/mcp';
let rpc = 9900;
const fill = color => [{ type: 'solid', color }];

async function call(name, args) {
  const response = await fetch(ep, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      accept: 'application/json, text/event-stream',
      'mcp-session-id': 'openpencil',
    },
    body: JSON.stringify({ jsonrpc: '2.0', id: rpc++, method: 'tools/call', params: { name, arguments: args } }),
  });
  const json = await response.json();
  if (json.error || json.result?.isError) throw new Error(JSON.stringify(json.error || json.result));
  const value = json.result.content?.[0]?.text;
  try { return value ? JSON.parse(value) : json.result; } catch { return value; }
}

async function children(pageId, frameId, groupName) {
  const frame = await call('read_nodes', { nodeIds: [frameId], depth: 1, pageId });
  const group = frame.nodes[0].children.find(node => node.name === groupName);
  const result = await call('read_nodes', { nodeIds: [group.id], depth: 1, pageId });
  return result.nodes[0].children || [];
}

(async () => {
  for (const [pageId, frameId, hideMarker] of [['n2191', 'n2192', false], ['n2390', 'n2391', true]]) {
    for (const node of await children(pageId, frameId, 'Foco de teclado · transición 100 ms')) {
      if (node.name === '06 focus label') {
        await call('update_node', { nodeId: node.id, data: { content: '' }, pageId });
      }
      if (node.name === '06 focus marker') {
        await call('update_node', { nodeId: node.id, data: { x: 288, width: 12, content: hideMarker ? '' : '>' }, pageId });
      }
    }
  }

  for (const node of await children('n2390', 'n2391', 'Selector controlado abierto · foco 100 ms')) {
    if (node.name === 'Selector query cover') {
      await call('update_node', { nodeId: node.id, data: { stroke: { thickness: 1, fill: fill('#D9D6CF') } }, pageId: 'n2390' });
    }
  }

  for (const node of await children('n2477', 'n2478', 'Paleta universal · foco 100 ms')) {
    if (node.name === 'Palette query field') {
      await call('update_node', { nodeId: node.id, data: { stroke: { thickness: 1, fill: fill('#D9D6CF') } }, pageId: 'n2477' });
    }
  }
})().catch(error => {
  console.error(error);
  process.exit(1);
});

